import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`notion-system-builder`,heroTitle:`Build your Notion system in minutes`,heroSubtitle:`Perplexity Computer designs your databases, views, and workflows, then delivers a complete Notion system with instructions — automatically.`,heroOverlaySteps:[`Analyzing your workflow requirements and template goals`,`Designing databases, properties, and relational structures`,`Building views, automations, and workflow instructions`,`Your complete Notion system documented and structured — ready to implement`],generatingSteps:[`Mapping your workflow requirements, goals, and scaling needs`,`Designing an agent to architect databases, views, and relational properties`,`Configuring workflow automations, templates, and documentation`,`Setting up your complete Notion system blueprint with step-by-step instructions`],featureSectionTitle:`From idea to Notion system`,featureCardTitles:[`Connects to your productivity stack`,`Outputs you can implement`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Notion, Google Sheets, Slack, Trello, Airtable — Computer designs systems that integrate with the tools you already use.`,`Database schemas with properties and relations. Filtered views for every use case. Workflow automations. Step-by-step build instructions you can follow in Notion.`],capabilitySectionTitle:`Your systems architect, on autopilot`,capabilitySectionSubtitle:`Describe your workflow, step away, get a complete Notion system blueprint.`,capabilityCards:[{title:`System Architecture`,description:`Computer can design interconnected databases with the right property types, relations, rollups, and formulas — structured to scale with your team.`},{title:`View Design`,description:`Computer can create filtered views, board layouts, timeline views, and gallery views — each tailored to a specific workflow or team role.`},{title:`Workflow Mapping`,description:`Computer can translate your processes into Notion automations, status flows, and recurring templates — so nothing falls through the cracks.`},{title:`Connect Your Tools`,description:`Computer can integrate with Notion, Slack, Google Sheets, Trello, and Airtable — build workflows that bridge your entire productivity stack.`},{title:`Remember & Refine`,description:`Computer can remember your workspace structure, naming conventions, and past systems — so every new build stays consistent with what you've already created.`},{title:`Monitor & Optimize`,description:`Computer can review your Notion usage patterns and flag when databases need restructuring, views need updating, or workflows need streamlining.`}]});export{t as default};
